package com.dao;import java.sql.*;import com.entity.User;import com.util.PasswordUtil;public class UserDao{private Connection c;public UserDao(Connection c){this.c=c;}public boolean register(User u){try(PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,email,password_hash) VALUES(?,?,?)")){p.setString(1,u.getFullName());p.setString(2,u.getEmail());p.setString(3,PasswordUtil.hash(u.getPassword()));return p.executeUpdate()==1;}catch(Exception e){e.printStackTrace();return false;}}public User login(String e,String pw){try(PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE email=?")){p.setString(1,e);ResultSet r=p.executeQuery();if(r.next()&&PasswordUtil.matches(pw,r.getString("password_hash"))){User u=new User();u.setId(r.getInt("id"));u.setFullName(r.getString("full_name"));u.setEmail(r.getString("email"));return u;}}catch(Exception x){x.printStackTrace();}return null;}}